import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse(`{"title":"React Native framework choice: Expo vs. Community CLI","description":"","frontmatter":{"id":2,"title":"React Native framework choice: Expo vs. Community CLI","status":"decided","date":"July 2026","author":"Claude Code (session with the developer)","scope":"mobile","summary":"Task 0.1.1 / epic 0.1 — which React Native toolchain the repo scaffold is built on, and which parts of that toolchain's hosted services are deliberately excluded","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/research/0002-react-native-framework-choice.md"},"headers":[],"relativePath":"sovereign-edge/research/0002-react-native-framework-choice.md","filePath":"sovereign-edge/research/0002-react-native-framework-choice.md"}`),n={name:"sovereign-edge/research/0002-react-native-framework-choice.md"};function r(s,e,c,d,l,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="research-0002-—-react-native-framework-choice-expo-vs-community-cli" tabindex="-1">Research 0002 — React Native framework choice: Expo vs. Community CLI <a class="header-anchor" href="#research-0002-—-react-native-framework-choice-expo-vs-community-cli" aria-label="Permalink to &quot;Research 0002 — React Native framework choice: Expo vs. Community CLI&quot;">​</a></h1><p><strong>Related:</strong> <a href="./0001-concept-and-connector-architecture.html">0001</a> decided React Native as the client framework but did not pick a toolchain. Affects epic <a href="./../epics/mobile/infrastructure.html">Infrastructure</a> tasks 0.1–0.4 and epic <a href="./../epics/mobile/mobile-app-shell.html">Mobile App Shell</a>.</p><hr><h2 id="question" tabindex="-1">Question <a class="header-anchor" href="#question" aria-label="Permalink to &quot;Question&quot;">​</a></h2><p><a href="./0001-concept-and-connector-architecture.html#decisions">0001</a> committed to React Native for iOS + Android from Phase 1, but left the toolchain unstated. Which React Native framework should task 0.1.1 scaffold on — and does anything about a sovereignty-first, provably-offline product argue against the ecosystem&#39;s default answer?</p><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><h3 id="the-framework-question-is-not-the-same-question-it-was" tabindex="-1">The framework question is not the same question it was <a class="header-anchor" href="#the-framework-question-is-not-the-same-question-it-was" aria-label="Permalink to &quot;The framework question is not the same question it was&quot;">​</a></h3><p>The React Native core team no longer recommends bare <code>react-native init</code> for new projects; the docs direct new apps to start with a framework, and name Expo as the one they endorse. The historical objection to Expo for this project&#39;s shape — &quot;on-device <code>llama.cpp</code> needs native code, so we need bare RN&quot; — no longer holds:</p><ul><li><strong><code>llama.rn</code> ships an Expo config plugin.</strong> It takes <code>enableEntitlements</code>, <code>forceCxx20</code>, and <code>enableOpenCL</code> options for exactly the iOS/OpenCL native configuration this app needs. There is a known <a href="https://github.com/mybigday/llama.rn/issues/243" target="_blank" rel="noreferrer">ESM resolution bug</a> in plugin loading — a bug to work around, not an architectural wall.</li><li><strong>Expo is no longer a one-way door.</strong> <code>expo prebuild</code> generates real <code>ios/</code> and <code>android/</code> directories. Committing them at any point yields Community-CLI-equivalent native control while keeping the <code>expo-*</code> module library and config-plugin system — the escape hatch is always one command away, which is what makes adopting Expo low-risk rather than binding.</li></ul><h3 id="what-expo-concretely-buys-this-specific-roadmap" tabindex="-1">What Expo concretely buys this specific roadmap <a class="header-anchor" href="#what-expo-concretely-buys-this-specific-roadmap" aria-label="Permalink to &quot;What Expo concretely buys this specific roadmap&quot;">​</a></h3><ul><li><strong>Task 0.4 (model asset pipeline).</strong> The epic names resumable download plus checksum verification as the fix for the stuck-download failure the developer hit evaluating OGAM. <code>expo-file-system</code>&#39;s <code>createDownloadResumable</code> is that primitive, already maintained and tested, rather than hand-rolled <code>RNFS</code> code.</li><li><strong>Task 0.3 (native build tooling).</strong> Signing, capabilities, and the Tier 3 native-module placeholder become declarative config-plugin state instead of hand-edited Xcode project files that drift between machines.</li><li><strong>Connector credential storage</strong> (epics 2.2, 4.2). <code>expo-secure-store</code> is Keychain/Keystore-backed, matching 0001&#39;s &quot;token stored in the OS keychain, scoped per-connector&quot; decision.</li></ul><h3 id="where-expo-s-defaults-conflict-with-the-product-s-trust-claim" tabindex="-1">Where Expo&#39;s defaults conflict with the product&#39;s trust claim <a class="header-anchor" href="#where-expo-s-defaults-conflict-with-the-product-s-trust-claim" aria-label="Permalink to &quot;Where Expo&#39;s defaults conflict with the product&#39;s trust claim&quot;">​</a></h3><p>Two of Expo&#39;s headline features are actively wrong for this product, and both are opt-out rather than opt-in:</p><ul><li><strong><code>expo-updates</code> (OTA JavaScript delivery)</strong> means the code actually running is not the code in the audited, store-reviewed binary. For an AGPL product whose entire proposition is verifiable local-only execution, a hot-swap channel undercuts task <a href="./../epics/mobile/core-inference-chat.html">1.5 / 0.1.12</a> (zero-network enforcement and audit) at the concept level, not merely at the packet level. It is also, unavoidably, a network callback in an app that claims to make none.</li><li><strong>EAS Build</strong> is a hosted third-party build service that would hold the project&#39;s signing keys. For a sovereignty-branded project that is an avoidable custody question; <code>eas build --local</code> or plain GitHub Actions produces the same artifacts without it.</li></ul><p>The residual cost of choosing Expo is a larger dependency surface for 0.1.12&#39;s audit to cover. That audit is empirical either way — run the app under packet capture, assert zero egress outside a granted connector — so the cost is breadth of review, not a different kind of work.</p><h2 id="options-considered" tabindex="-1">Options considered <a class="header-anchor" href="#options-considered" aria-label="Permalink to &quot;Options considered&quot;">​</a></h2><h3 id="a-expo-with-continuous-native-generation-recommended" tabindex="-1">A. Expo, with continuous native generation (recommended) <a class="header-anchor" href="#a-expo-with-continuous-native-generation-recommended" aria-label="Permalink to &quot;A. Expo, with continuous native generation (recommended)&quot;">​</a></h3><p>Full <code>expo-*</code> module library and config plugins, no dependency on Expo&#39;s hosted services. Ecosystem-default tooling, which matters for a solo/small- team Phase 1.</p><p><code>ios/</code> and <code>android/</code> stay <strong>generated, not committed</strong>. Committing them alongside <code>prebuild</code> is the worst of both worlds: <code>prebuild</code> overwrites hand-edits, so the native projects become a source of merge noise and silent drift — exactly the failure mode that choosing Expo was meant to avoid. With CNG, <code>app.json</code> plus config plugins are the single source of truth, which is what makes task 0.3&#39;s &quot;declarative native config&quot; benefit real. Committing them remains available later as a deliberate migration, not a default.</p><h3 id="b-react-native-community-cli-bare-react-native-no-framework" tabindex="-1">B. <code>@react-native-community/cli</code> (&quot;bare&quot; React Native, no framework) <a class="header-anchor" href="#b-react-native-community-cli-bare-react-native-no-framework" aria-label="Permalink to &quot;B. `@react-native-community/cli` (&quot;bare&quot; React Native, no framework)&quot;">​</a></h3><p>Smallest dependency surface, which is the one thing it wins on. Costs hand-rolled equivalents of <code>expo-file-system</code>&#39;s resumable downloads and <code>expo-secure-store</code>, plus the well-known RN upgrade tax. Discouraged by React Native&#39;s own docs for new apps.</p><h3 id="c-rock-formerly-react-native-enterprise-framework-rnef-by-callstack" tabindex="-1">C. Rock (formerly React Native Enterprise Framework / <code>rnef</code>, by Callstack) <a class="header-anchor" href="#c-rock-formerly-react-native-enterprise-framework-rnef-by-callstack" aria-label="Permalink to &quot;C. Rock (formerly React Native Enterprise Framework / `rnef`, by Callstack)&quot;">​</a></h3><p>The only genuine third framework. Keeps bare native projects, adds a CLI, pluggable bundlers, out-of-tree platform support, and native build caching <strong>hosted on your own infrastructure</strong> via GitHub Actions — which maps directly onto the EAS key-custody objection above. Rejected for now on two grounds: it targets teams who have <em>outgrown</em> the Community CLI on large modular codebases, and Callstack themselves point new projects at Expo. Its self-hosted-build advantage is obtainable anyway via <code>expo prebuild</code> plus GitHub Actions.</p><p>Worth remembering as the migration target if Expo&#39;s dependency surface ever collides with 0.1.12. Migration is plausible precisely because both A and C leave real native projects on disk.</p><h3 id="not-considered-further" tabindex="-1">Not considered further <a class="header-anchor" href="#not-considered-further" aria-label="Permalink to &quot;Not considered further&quot;">​</a></h3><p><strong>Ignite</strong> (Infinite Red) is frequently listed as an alternative but is a boilerplate generated <em>on top of</em> Expo or the Community CLI — orthogonal to this choice, layerable onto either.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to &quot;Recommendation&quot;">​</a></h2><p>Adopt Option A: <strong>Expo with <code>prebuild</code>, excluding <code>expo-updates</code> and EAS.</strong></p><p>Leave <code>expo-updates</code> out of the template from the first commit. Retrofitting its absence later is harder than never adding it, and its presence would have to be explained away in every subsequent claim the product makes about offline verifiability.</p><h2 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h2><ul><li><strong>Toolchain:</strong> Expo, using continuous native generation. <code>ios/</code> and <code>android/</code> are gitignored and regenerated by <code>expo prebuild</code>; <code>app.json</code> plus config plugins are the source of truth for native configuration.</li><li><strong>Boot verification happens in CI, not on a developer laptop.</strong> The local machine can build neither platform — CocoaPods cannot be installed (Homebrew under <code>/opt/homebrew</code> belongs to a different macOS account; system Ruby is 2.6, below current CocoaPods&#39; minimum), and no Android SDK or JDK exists. Rather than chase a per-laptop fix, epic <a href="./../epics/mobile/infrastructure.html">0.1</a>&#39;s &quot;boots on both platforms&quot; check is satisfied by GitHub Actions runners, which ship CocoaPods, a JDK, and the Android SDK. This makes the check reproducible instead of dependent on one machine&#39;s setup, and it follows from the no-EAS decision above.</li><li><strong>No <code>expo-updates</code>.</strong> No over-the-air JavaScript delivery, ever. The shipped binary is the audited binary.</li><li><strong>No EAS Build.</strong> Builds run locally or in GitHub Actions (task 0.2); the project holds its own signing keys.</li><li><strong>Expo Go is not a supported development path</strong> — <code>llama.rn</code> requires a development build, so iOS/Android dev builds are the only workflow.</li><li><strong>Test runner: Jest via <code>jest-expo</code></strong>, a deliberate exception to the ecosystem&#39;s Vitest 4 standard rather than drift. React Native ships Flow types in its own source and resolves modules Metro-style; Vitest needs preset and transform workarounds to cope, and those break on RN upgrades. <code>jest-expo</code> is maintained in lockstep with the SDK. The cost is one inconsistency with <code>sovereign-desktop</code>; the benefit is a test setup that survives SDK bumps without hand-holding.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li><strong>Whether CI should also gate on a physical device.</strong> The simulator and emulator checks in <code>native.yml</code> catch crash-on-startup, but not the device-only failures (memory pressure under a loaded GGUF model, thermal throttling) that matter most for on-device inference. Task 0.3 revisits this when real builds start going to TestFlight and the internal Play track.</li><li><s><strong>Whether the <code>llama.rn</code> config-plugin ESM bug is still live</strong></s> — <strong>resolved.</strong> Not present at <code>llama.rn</code> 0.12.8: the plugin resolves and <code>expo prebuild</code> completes with it active, and the Android build links <code>:llama.rn:assembleDebug</code> and packages <code>librnllama*.so</code> into the APK. No patch needed.</li><li><strong><code>llama.rn</code> ships prebuilt native binaries rather than building from source.</strong> Its <code>postinstall</code> downloads <code>llama-rn-ios-xcframework.tar.gz</code> and <code>llama-rn-android-jni-libs.tar.gz</code>, which are too large for npm. For a product whose claim is verifiable local execution, the inference engine&#39;s binaries arriving over the network at install time is a supply-chain link worth a deliberate decision — accept them, pin and checksum them, or build from source. Unresolved.</li><li><strong>Debug APK size grew from 130 MB to 226 MB</strong> when <code>llama.rn</code> was added, as it ships a native library per CPU feature variant (v8, v8_2, dotprod, i8mm, hexagon, opencl) for both ABIs. A release build wants ABI splits and no x86_64 slice; revisit at task 0.3 or 8.2.</li><li><strong>Local Android toolchain.</strong> Nothing is installed — no SDK, no <code>ANDROID_HOME</code>, no Android Studio, no <code>adb</code>, and no Java runtime at all. Deferred deliberately: JDK plus the Android command-line tools unpack into <code>$HOME</code> without <code>sudo</code> or Homebrew, so this is unblocked whenever local Android work actually starts.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p>Task 0.1.1 scaffolds on this decision. Task 0.2 (CI pipeline) inherits the &quot;no EAS&quot; constraint, must build on GitHub Actions runners, and now also carries 0.1&#39;s boot check — 0.1.1 stays open until CI proves the app launches on both platforms. Task 0.1.12 (zero-network enforcement and audit) should treat this doc&#39;s dependency- surface caveat as a named input — the audit&#39;s scope includes every <code>expo-*</code> package the app ends up shipping.</p>',35)])])}const m=o(n,[["render",r]]);export{p as __pageData,m as default};
